                __global__ void add_kernel(const float* a, const float* b, int size) {
                    int idx = blockIdx.x * blockDim.x + threadIdx.x;
                    if (idx < size) {
                        a[idx] += b[idx];
                    }
                }

                // Function to create the CUDA kernel
                torch::Tensor add_kuda(torch::Tensor a, torch::Tensor b) {
                    auto size = a.numel();
                    auto out = torch::zeros_like(a);

                    const int block_size = 256;
                    const int num_blocks = (size + block_size - 1) / block_size;

                    add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

                    return out;
                }
            """,
            functions=["add_cuda"],
            verbose=True,
            extra_cflags=[],
            extra_ldflags=[]
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the 2D convolution.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, height_out, width_out).
        """
        # Custom CUDA operator for element-wise addition
        return self.add_cuda(x)

